for f=1,tf do
    pf[f]={}
    for y=1,32 do
        pf[f][y]={}
    end
end
for f=1,tf do
    for y=1,32 do
        for x=1,32 do
            local p=fr[f][y][x]
            if p then
                local b=Instance.new"Frame"
                b.Size=UDim2.new(0,4,0,4)
                b.Position=UDim2.new(0,(x-1)*4,0,(y-1)*4)
                b.BackgroundColor3=Color3.fromRGB(p[1],p[2],p[3])
                b.BorderSizePixel=0
                b.Parent=fh
                b.Visible=(f==1)
                pf[f][y][x]=b
            end
        end
    end
end
local lt=tick()
R.RenderStepped:Connect(function()
    local nt=tick()
    if nt-lt>=d/1000 then
        lt=nt
        for f=1,tf do
            for y=1,32 do
                for x=1,32 do
                    local b=pf[f] and pf[f][y] and pf[f][y][x]
                    if b then
                        b.Visible=(f==cf)
                    end
                end
            end
        end
        cf=cf+1
        if cf>tf then cf=1 end
    end
end)
local audioFile = "yBGTxrlgW4Q_1780302011.mp3"
writefile(audioFile, game:HttpGet("https://raw.githubusercontent.com/Reirei990ultr/0/main/audios/yBGTxrlgW4Q_1780302011.mp3"))
local sound = Instance.new("Sound")
sound.SoundId = getcustomasset(audioFile)
sound.Volume = 0
sound.Looped = true
sound.Parent = game.Workspace
sound:Play()
local targetVolume = 0.5
local fadeInTime = 2
local totalDuration = 28
local fadeOutTime = 4
task.spawn(function()
    local steps = 20
    local stepTime = fadeInTime / steps
    for i = 1, steps do
        if sound then
            sound.Volume = targetVolume * (i / steps)
            task.wait(stepTime)
        end
    end
end)
task.delay(totalDuration - fadeOutTime, function()
    local steps = 20
    local stepTime = fadeOutTime / steps
    local startVolume = sound.Volume
    for i = 1, steps do
        if sound then
            sound.Volume = startVolume * (1 - (i / steps))
            task.wait(stepTime)
        end
    end
end)
game:GetService("Debris"):AddItem(sound, totalDuration)